import type { Topic } from '../types';
import { builtin } from './util';

/** Opracowanie własne skanu rodzica; zakres i uwagi: docs/HISTORY_CHAPTER2.md. */
export const HISTORY_CHAPTER2 = 'Rozdział 2. Starożytna Grecja';
const join = (xs: string[]) => xs.join('\n');
const choice = (q: string, a: string, wrong: string[], why: string) =>
  `wybierz: ${q} | *${a} | ${wrong.join(' | ')} !! ${why}`;
const fill = (q: string, body: string, why: string) => `wpisz: ${q} >> ${body} !! ${why}`;
const match = (q: string, pairs: string[], why: string) => `pary: ${q} >> ${pairs.join(' ; ')} !! ${why}`;
const truth = (q: string, yes: boolean, why: string) => choice(q, yes ? 'Prawda' : 'Fałsz', [yes ? 'Fałsz' : 'Prawda'], why);
type LessonData = { key: string[]; lists: Record<string, string[]>; steps: string[]; pairs: string[]; trick: string[]; checks: string[] };
function topic(slug: string, order: number, title: string, description: string, exercises: string[], guide: string[], l: LessonData): Topic {
  if (exercises.length !== 28) throw new Error(`${slug}: zamiast 28 pytań jest ${exercises.length}`);
  return { ...builtin(`b-h5-r2-${slug}`, 'his', order, title, description, join(exercises), [5]),
    unit: HISTORY_CHAPTER2, updatedAt: '2026-10-31T14:00:00.000Z', guide: join(guide),
    lesson: join(['# Najważniejsze', ...l.key, ...Object.entries(l.lists).flatMap(([name, rows]) => [`## ${name}`, ...rows]),
      '# Krok po kroku', ...l.steps, '# Tak / nie tak', ...l.pairs, '# Zapamiętaj', ...l.trick, '# Sprawdź się', ...l.checks]) };
}

